98	  transformOut(code: string): [string, number] {
99	    // Get the quote type from the last transformIn
100	    const prefix = this.lastQuotePrefix;
101	
102	    // Empty string
103	    if (code === "") {
104	      // Need at least a space, otherwise the output will be 6 quotes
105	      code = " ";
106	    }
107	
108	    // We always transform back with triple quotes, as to avoid needing to
109	    // escape single quotes.
110	    const escapedCode = code.replaceAll('"""', String.raw`\"""`);
111	
112	    // If its one line and not bounded by quotes, write it as single line
113	    const isOneLine = !code.includes("\n");
114	    const boundedByQuote = code.startsWith('"') || code.endsWith('"');
115	    if (isOneLine && !boundedByQuote) {
116	      const start = `mo.md(${prefix}"""`;
117	      const end = `""")`;
118	      return [start + escapedCode + end, start.length];
119	    }
120	
121	    // Multiline code
122	    const start = `mo.md(\n    ${prefix}"""\n`;
123	    const end = `\n    """\n)`;
124	    return [start + indentOneTab(escapedCode) + end, start.length + 1];
125	  }
