// Node names for the embedded Python interpolation blocks.
const PYTHON = "Python";
const PYTHON_MARK = "PythonMark";

// Character codes for the curly braces that delimit an interpolation block.
const CHAR_CODES = {
  OPEN_BRACE: 123, // {
  CLOSE_BRACE: 125, // }
};

/**
 * Define a parser for Python interpolation blocks (e.g. `{variable}`) inside
 * Markdown. The content between a single pair of curly braces is parsed as
 * Python so that it can be highlighted and completed.
 *
 * A double open curly brace (`{{`) is treated as an escaped literal and is not
 * parsed as an interpolation block.
 *
 * @param pythonParser CodeMirror {@link Parser} for Python.
 * @param isActivated Whether embedded Python parsing is currently enabled.
 * @returns Markdown extension.
 */
export function parsePython(
  pythonParser: Parser,
  isActivated: () => boolean,
): MarkdownConfig {
  const defineNodes: NodeSpec[] = [
    { name: PYTHON, style: tags.emphasis },
    { name: PYTHON_MARK, style: tags.processingInstruction },
  ];

  return {
    defineNodes,
    parseInline: [
      {
        name: PYTHON,
        parse(cx: InlineContext, next: number, pos: number): number {
          // Only handle an opening curly brace.
          if (next !== CHAR_CODES.OPEN_BRACE) {
            return -1;
          }

          // Embedded Python parsing must be enabled.
          if (!isActivated()) {
            return -1;
          }

          // A double open curly brace (`{{`) is an escaped literal, not an
          // interpolation block.
          if (cx.char(pos + 1) === CHAR_CODES.OPEN_BRACE) {
            return -1;
          }

          // Find the matching closing brace on this inline section.
          let end = -1;
          for (let i = pos + 1; i < cx.end; i++) {
            const ch = cx.char(i);
            if (ch === CHAR_CODES.CLOSE_BRACE) {
              end = i;
              break;
            }
            // Bail out on a nested open brace; we don't support nesting.
            if (ch === CHAR_CODES.OPEN_BRACE) {
              return -1;
            }
          }

          // No closing brace found.
          if (end === -1) {
            return -1;
          }

          const openMark = cx.elt(PYTHON_MARK, pos, pos + 1);
          const closeMark = cx.elt(PYTHON_MARK, end, end + 1);
          return cx.addElement(
            cx.elt(PYTHON, pos, end + 1, [openMark, closeMark]),
          );
        },
      },
    ],
    wrap: parseMixed((node) => {
      if (node.type.name !== PYTHON) {
        return null;
      }

      // Overlay the Python parser onto the content between the braces,
      // excluding the braces themselves.
      const from = node.from + 1;
      const to = node.to - 1;
      if (from >= to || from < 0 || to < 0) {
        return null;
      }

      return {
        parser: pythonParser,
        overlay: [{ from, to }],
      };
    }),
  };
}

/**
 * Build completion options from the current variables state.
 */
function getVariableCompletions(): Completion[] {
  const variables = store.get(variablesAtom);
  return Object.values(variables).map(
    (variable): Completion => ({
      label: variable.name,
      displayLabel: variable.name,
      type: "variable",
      detail: variable.dataType ?? undefined,
      boost: 1,
    }),
  );
}

/**
 * A CodeMirror extension that provides variable-name completions inside
 * embedded Python interpolation blocks.
 *
 * @param isActivated Whether embedded Python completions are currently enabled.
